<?php
declare(strict_types=1);
final class TaskEnvelopeService {
 private const ACTIONS=['workspace.read','workspace.write'];private const MAX_TTL=300;private const MAX_PAYLOAD_BYTES=16384;
 public function __construct(private PDO $db,private Crypto $crypto){}
 public function registerSigningKey(string $deviceId):array{
  $this->assertDevice($deviceId);$q=$this->db->prepare('SELECT public_key,revoked_at FROM device_signing_keys WHERE device_id=?');$q->execute([$deviceId]);$old=$q->fetch();if($old&&$old['revoked_at']===null){$raw=base64_decode($old['public_key'],true);if($raw===false||strlen($raw)!==SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES)throw new RuntimeException('Stored public signing key is invalid.');return ['device_id'=>$deviceId,'public_key'=>$old['public_key'],'key_id'=>hash('sha256',$raw)];}
