 }
 public function localPublicKey(string $deviceId):string{$this->assertDevice($deviceId);$q=$this->db->prepare('SELECT public_key,revoked_at FROM device_signing_keys WHERE device_id=?');$q->execute([$deviceId]);$row=$q->fetch();if(!$row||$row['revoked_at']!==null)throw new RuntimeException('No active local signing key exists for this device.');$raw=base64_decode($row['public_key'],true);if($raw===false||strlen($raw)!==SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES)throw new RuntimeException('Stored device public key is invalid.');return $raw;}
 public function trustDeviceSigningKey(string $deviceId,string $publicKey,string $approvedBy,bool $allowRotation=false):void{$this->assertDevice($deviceId);$this->assertDevice($approvedBy);if($deviceId===$approvedBy)throw new InvalidArgumentException('A device cannot approve its own remote signing key.');if(strlen($publicKey)!==SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES)throw new InvalidArgumentException('Trusted public key has an invalid length.');$q=$this->db->prepare('SELECT public_key,revoked_at FROM trusted_device_signing_keys WHERE device_id=?');$q->execute([$deviceId]);$old=$q->fetch();$encoded=base64_encode($publicKey);if($old&&$old['revoked_at']!==null&&!$allowRotation)throw new RuntimeException('Trusted device signing key was revoked. Explicit re-approval is required.');if($old&&$old['revoked_at']===null&&!hash_equals((string)$old['public_key'],$encoded)&&!$allowRotation)throw new RuntimeException('Trusted device signing key changed. Explicit re-approval is required.');$now=date(DATE_ATOM);$q=$this->db->prepare('INSERT INTO trusted_device_signing_keys(device_id,public_key,approved_by,approved_at,revoked_at) VALUES(?,?,?,?,NULL) ON CONFLICT(device_id) DO UPDATE SET public_key=excluded.public_key,approved_by=excluded.approved_by,approved_at=excluded.approved_at,revoked_at=NULL');$q->execute([$deviceId,$encoded,$approvedBy,$now]);}
 public function revokeTrustedDeviceSigningKey(string $deviceId):void{$this->assertDevice($deviceId);$q=$this->db->prepare('UPDATE trusted_device_signing_keys SET revoked_at=? WHERE device_id=? AND revoked_at IS NULL');$q->execute([date(DATE_ATOM),$deviceId]);}
 private function approvedPublicKey(string $deviceId):string{$this->assertDevice($deviceId);$q=$this->db->prepare('SELECT public_key,revoked_at FROM trusted_device_signing_keys WHERE device_id=?');$q->execute([$deviceId]);$row=$q->fetch();if(!$row||$row['revoked_at']!==null)throw new RuntimeException('Issuer signing key has not been explicitly trusted or has been revoked.');$raw=base64_decode($row['public_key'],true);if($raw===false||strlen($raw)!==SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES)throw new RuntimeException('Trusted device public key is invalid.');return $raw;}
 public function revokeSigningKey(string $deviceId):void{$this->assertDevice($deviceId);$q=$this->db->prepare('UPDATE device_signing_keys SET revoked_at=? WHERE device_id=? AND revoked_at IS NULL');$q->execute([date(DATE_ATOM),$deviceId]);}
 public function issue(string $issuerDeviceId,string $targetDeviceId,string $action,array $payload,int $ttlSeconds=120,?string $taskId=null):array{
  $this->assertDevice($issuerDeviceId);$this->assertDevice($targetDeviceId);if($issuerDeviceId===$targetDeviceId)throw new InvalidArgumentException('A task envelope must target a different device.');if(!in_array($action,self::ACTIONS,true))throw new InvalidArgumentException('Task action is not in the supported envelope allowlist.');$this->assertPayloadAction($action,$payload);if($ttlSeconds<15||$ttlSeconds>self::MAX_TTL)throw new InvalidArgumentException('Task envelope lifetime must be between 15 and 300 seconds.');$payloadJson=$this->canonicalJson($payload);if(strlen($payloadJson)>self::MAX_PAYLOAD_BYTES)throw new InvalidArgumentException('Task envelope payload exceeds 16 KB.');
  $key=$this->loadSecretKey($issuerDeviceId);$public=$this->localPublicKey($issuerDeviceId);$keyId=hash('sha256',$public);$now=time();$id='env_'.bin2hex(random_bytes(16));$envelope=['schema_version'=>1,'envelope_id'=>$id,'issuer_device_id'=>$issuerDeviceId,'issuer_key_id'=>$keyId,'task_id'=>$taskId,'target_device_id'=>$targetDeviceId,'action'=>$action,'issued_at'=>gmdate('Y-m-d\\TH:i:s\\Z',$now),'expires_at'=>gmdate('Y-m-d\\TH:i:s\\Z',$now+$ttlSeconds),'nonce'=>bin2hex(random_bytes(24)),'payload'=>$payload];$signature=sodium_crypto_sign_detached($this->canonicalJson($envelope),$key);sodium_memzero($key);
  $q=$this->db->prepare("INSERT INTO task_envelopes(envelope_id,issuer_device_id,target_device_id,action,payload_hash,status,expires_at,created_at,task_id) VALUES(?,?,?,?,?,'issued',?,?,?)");$q->execute([$id,$issuerDeviceId,$targetDeviceId,$action,hash('sha256',$payloadJson),$envelope['expires_at'],date(DATE_ATOM),$taskId]);return ['envelope'=>$envelope,'signature'=>base64_encode($signature),'key_id'=>$keyId];
 }
 public function verifyAndConsume(array $envelope,string $signature,string $expectedTargetDeviceId):array{
  $this->assertDevice($expectedTargetDeviceId);$required=['schema_version','envelope_id','issuer_device_id','issuer_key_id','task_id','target_device_id','action','issued_at','expires_at','nonce','payload'];$keys=array_keys($envelope);sort($keys);sort($required);if($keys!==$required)throw new InvalidArgumentException('Task envelope fields do not match schema version 1.');if(($envelope['schema_version']??null)!==1||!is_array($envelope['payload']??null))throw new InvalidArgumentException('Unsupported task envelope schema.');$this->assertDevice((string)$envelope['issuer_device_id']);$this->assertDevice((string)$envelope['target_device_id']);if($envelope['task_id']!==null&&(!is_string($envelope['task_id'])||!preg_match('/^[A-Za-z0-9_-]{1,100}$/',$envelope['task_id'])))throw new InvalidArgumentException('Task envelope task ID is invalid.');if(!in_array($envelope['action'],self::ACTIONS,true))throw new InvalidArgumentException('Task action is not in the supported envelope allowlist.');$this->assertPayloadAction((string)$envelope['action'],$envelope['payload']);if(!hash_equals($expectedTargetDeviceId,(string)$envelope['target_device_id']))throw new RuntimeException('Task envelope is addressed to a different device.');if(!preg_match('/^env_[a-f0-9]{32}$/',(string)$envelope['envelope_id'])||!preg_match('/^[a-f0-9]{48}$/',(string)$envelope['nonce']))throw new InvalidArgumentException('Task envelope identifier or nonce is invalid.');
  $issued=strtotime((string)$envelope['issued_at']);$expires=strtotime((string)$envelope['expires_at']);$now=time();if($issued===false||$expires===false||$issued>$now+60||$expires<=$now||$expires<=$issued||($expires-$issued)>self::MAX_TTL)throw new RuntimeException('Task envelope is expired or outside its allowed time window.');$payloadJson=$this->canonicalJson($envelope['payload']);if(strlen($payloadJson)>self::MAX_PAYLOAD_BYTES)throw new InvalidArgumentException('Task envelope payload exceeds 16 KB.');$trustedIssuerPublicKey=$this->approvedPublicKey((string)$envelope['issuer_device_id']);if(!hash_equals(hash('sha256',$trustedIssuerPublicKey),(string)$envelope['issuer_key_id']))throw new RuntimeException('Task envelope issuer key ID is not trusted.');$sig=base64_decode($signature,true);if($sig===false||strlen($sig)!==SODIUM_CRYPTO_SIGN_BYTES)throw new InvalidArgumentException('Task envelope signature has an invalid format.');if(!sodium_crypto_sign_verify_detached($sig,$this->canonicalJson($envelope),$trustedIssuerPublicKey))throw new RuntimeException('Task envelope signature verification failed.');
  $this->db->beginTransaction();try{$q=$this->db->prepare('SELECT status FROM task_envelopes WHERE envelope_id=?');$q->execute([$envelope['envelope_id']]);$existing=$q->fetchColumn();if($existing==='consumed')throw new RuntimeException('Task envelope replay detected.');if($existing!==false&&$existing!=='issued')throw new RuntimeException('Task envelope is not in an acceptable state.');$nowIso=date(DATE_ATOM);$hash=hash('sha256',$payloadJson);if($existing==='issued'){$q=$this->db->prepare("UPDATE task_envelopes SET status='consumed',consumed_at=? WHERE envelope_id=? AND status='issued'");$q->execute([$nowIso,$envelope['envelope_id']]);if($q->rowCount()!==1)throw new RuntimeException('Task envelope was consumed concurrently.');}else{$q=$this->db->prepare("INSERT INTO task_envelopes(envelope_id,issuer_device_id,target_device_id,action,payload_hash,status,expires_at,created_at,consumed_at) VALUES(?,?,?,?,?,'consumed',?,?,?)");$q->execute([$envelope['envelope_id'],$envelope['issuer_device_id'],$envelope['target_device_id'],$envelope['action'],$hash,$envelope['expires_at'],$nowIso,$nowIso]);}$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
  return ['accepted'=>true,'envelope_id'=>$envelope['envelope_id'],'issuer_device_id'=>$envelope['issuer_device_id'],'target_device_id'=>$envelope['target_device_id'],'task_id'=>$envelope['task_id'],'action'=>$envelope['action'],'payload'=>$envelope['payload'],'issuer_key_id'=>$envelope['issuer_key_id'],'payload_hash'=>$hash,'consumed_at'=>$nowIso];
 }
 public function signPayload(string $deviceId,array $payload):string{$key=$this->loadSecretKey($deviceId);$signature=sodium_crypto_sign_detached($this->canonicalJson($payload),$key);sodium_memzero($key);return base64_encode($signature);}
 public function verifyPayload(string $publicKey,array $payload,string $signature):bool{if(strlen($publicKey)!==SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES)return false;$sig=base64_decode($signature,true);if($sig===false||strlen($sig)!==SODIUM_CRYPTO_SIGN_BYTES)return false;return sodium_crypto_sign_verify_detached($sig,$this->canonicalJson($payload),$publicKey);}
 public function acknowledgeIssued(string $envelopeId,string $targetDeviceId,string $taskId):void{$this->assertDevice($targetDeviceId);if(!preg_match('/^env_[a-f0-9]{32}$/',$envelopeId)||$taskId==='')throw new InvalidArgumentException('Invalid task envelope acknowledgement.');$q=$this->db->prepare("UPDATE task_envelopes SET status='consumed',consumed_at=? WHERE envelope_id=? AND target_device_id=? AND task_id=? AND status='issued'");$q->execute([date(DATE_ATOM),$envelopeId,$targetDeviceId,$taskId]);if($q->rowCount()!==1)throw new RuntimeException('Issued task envelope does not match this device/task or was already acknowledged.');}
 private function loadSecretKey(string $deviceId):string{$q=$this->db->prepare('SELECT private_key_enc,revoked_at FROM device_signing_keys WHERE device_id=?');$q->execute([$deviceId]);$row=$q->fetch();if(!$row||$row['revoked_at']!==null)throw new RuntimeException('Device has no active signing key.');$secret=base64_decode($this->crypto->decrypt($row['private_key_enc']),true);if($secret===false||strlen($secret)!==SODIUM_CRYPTO_SIGN_SECRETKEYBYTES)throw new RuntimeException('Stored device signing key is invalid.');return $secret;}
 private function assertPayloadAction(string $action,array $payload):void{$actions=$payload['actions']??null;if(!is_array($actions)||!array_is_list($actions)||count($actions)<1||count($actions)>20)throw new InvalidArgumentException('Workspace task payload must contain 1–20 actions.');$hasWrite=false;foreach($actions as $item){if(!is_array($item))throw new InvalidArgumentException('Workspace task action must be an object.');$type=(string)($item['type']??'');if(in_array($type,['write_file','create_directory'],true))$hasWrite=true;elseif(!in_array($type,['read_file','list_directory'],true))throw new InvalidArgumentException('Workspace task contains an unsupported action.');}if($action==='workspace.read'&&$hasWrite)throw new InvalidArgumentException('A read-only envelope cannot contain workspace write actions.');if($action==='workspace.write'&&!$hasWrite)throw new InvalidArgumentException('A workspace-write envelope must contain at least one write action.');}
 private function canonicalJson(array $value):string{$normalize=function($v)use(&$normalize){if(!is_array($v))return $v;if(array_is_list($v))return array_map($normalize,$v);ksort($v,SORT_STRING);foreach($v as $k=>$item)$v[$k]=$normalize($item);return $v;};return json_encode($normalize($value),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR);}
 private function assertDevice(string $id):void{if(!preg_match('/^[A-Za-z0-9_-]{1,80}$/',$id))throw new InvalidArgumentException('Invalid device identifier.');}
}
